    {<< 3{b, {<< 5{a}}, c}} = 20'b01001000100100101011;
    $display("<<3 <<5 middle blocking %b %b %b %b %b %b %b", a, b, c, d[0], d[1], st.x, st.y);
    // <<3 <<5 deep blocking
    a = 0; b = 0; c = 0; d = '{0, 0}; st = '{0, 0};
    {<< 3{{<< 5{c, {<< 3{b, st}}}}, a}} = 29'b10010100111110000010101000000;
    $display("<<3 <<5 deep blocking %b %b %b %b %b %b %b", a, b, c, d[0], d[1], st.x, st.y);
    // <<4 >> first nba
    a = 0; b = 0; c = 0; d = '{0, 0}; st = '{0, 0};
    {<< 4{{>>{a, b}}, c}} <= 20'b10011000000101010101;
    #1;
    $display("<<4 >> first nba %b %b %b %b %b %b %b", a, b, c, d[0], d[1], st.x, st.y);
    // <<4 >> first delayed
    a = 0; b = 0; c = 0; d = '{0, 0}; st = '{0, 0};
    {<< 4{{>>{a, b}}, c}} <= #1 20'b00111111110101101010;
    #2;
    $display("<<4 >> first delayed %b %b %b %b %b %b %b", a, b, c, d[0], d[1], st.x, st.y);
    // <<4 <<2 first nba
    a = 0; b = 0; c = 0; d = '{0, 0}; st = '{0, 0};
    {<< 4{{<< 2{a, b}}, c}} <= 20'b11100111100101111111;
    #1;
    $display("<<4 <<2 first nba %b %b %b %b %b %b %b", a, b, c, d[0], d[1], st.x, st.y);
    // <<4 <<2 first delayed
    a = 0; b = 0; c = 0; d = '{0, 0}; st = '{0, 0};
    {<< 4{{<< 2{a, b}}, c}} <= #1 20'b10001111010110010100;
    #2;
    $display("<<4 <<2 first delayed %b %b %b %b %b %b %b", a, b, c, d[0], d[1], st.x, st.y);
    // <<4 <<4 first nba
    a = 0; b = 0; c = 0; d = '{0, 0}; st = '{0, 0};
    {<< 4{{<< 4{a, b}}, c}} <= 20'b00110111000110101001;
    #1;
    $display("<<4 <<4 first nba %b %b %b %b %b %b %b", a, b, c, d[0], d[1], st.x, st.y);
    // <<4 <<4 first delayed
    a = 0; b = 0; c = 0; d = '{0, 0}; st = '{0, 0};
    {<< 4{{<< 4{a, b}}, c}} <= #1 20'b11011110110110111110;
    #2;
    $display("<<4 <<4 first delayed %b %b %b %b %b %b %b", a, b, c, d[0], d[1], st.x, st.y);
    // <<4 <<5 first nba
    a = 0; b = 0; c = 0; d = '{0, 0}; st = '{0, 0};
    {<< 4{{<< 5{a, b}}, c}} <= 20'b10000110100111010011;
    #1;
    $display("<<4 <<5 first nba %b %b %b %b %b %b %b", a, b, c, d[0], d[1], st.x, st.y);
    // <<4 <<5 first delayed
    a = 0; b = 0; c = 0; d = '{0, 0}; st = '{0, 0};
    {<< 4{{<< 5{a, b}}, c}} <= #1 20'b00101110010111101000;
    #2;
    $display("<<4 <<5 first delayed %b %b %b %b %b %b %b", a, b, c, d[0], d[1], st.x, st.y);
    local_targets();
  end
endmodule
